SELECT * FROM (SELECT 'training_sessions' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.training_sessions t UNION ALL SELECT 'training_session_records' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.training_session_records t UNION ALL SELECT 'training_block_results' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.training_block_results t UNION ALL SELECT 'training_exercise_results' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.training_exercise_results t UNION ALL SELECT 'training_set_results' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.training_set_results t UNION ALL SELECT 'performance_result_corrections' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.performance_result_corrections t UNION ALL SELECT 'coach_athlete_relationships' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.coach_athlete_relationships t UNION ALL SELECT 'profiles' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.profiles t UNION ALL SELECT 'programme_assignments' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_assignments t UNION ALL SELECT 'programme_slot_outcomes' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_slot_outcomes t UNION ALL SELECT 'programme_schedule_occurrences' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_schedule_occurrences t UNION ALL SELECT 'programme_schedule_projections' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_schedule_projections t UNION ALL SELECT 'programme_version_session_slots' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_version_session_slots t UNION ALL SELECT 'programme_version_days' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_version_days t UNION ALL SELECT 'programme_version_weeks' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_version_weeks t UNION ALL SELECT 'programme_versions' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_versions t UNION ALL SELECT 'programme_publication_artifacts' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_publication_artifacts t UNION ALL SELECT 'programme_occurrence_running_target_snapshots' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.programme_occurrence_running_target_snapshots t UNION ALL SELECT 'session_blocks' AS relation,count(*) AS row_count,md5(coalesce(string_agg(to_jsonb(t)::text,chr(10) ORDER BY to_jsonb(t)::text),'')) AS rowset_md5 FROM public.session_blocks t) counts ORDER BY relation;
